#include <stdio.h>
#define MAX(a, b) ((a) > (b) ? (a) : (b))

int main(void) {
    int x = 2, y = 3;
    int m1 = MAX(x, y);
    printf("MAX(2,3) = %d\n", m1);

    int i = 0;
    /* 参数 i++ 被求值两次：一次比较、一次返回 */
    int m2 = MAX(i++, 2);
    printf("MAX(i++, 2) = %d (i 被求值两次后 = %d)\n", m2, i);
    return 0;
}
